from Crypto.Util.number import long_to_bytes
import math

def solve(N, ct1, ct2, e=65537):
    def poly_mult(p1, p2, ct2, N):
        a1, b1 = p1
        a2, b2 = p2
        a = (a1 * b2 + a2 * b1) % N
        b = (b1 * b2 + a1 * a2 * ct2) % N
        return (a, b)
    
    base = (1, 0)
    res_poly = (0, 1)
    exp = e
    while exp:
        if exp & 1:
            res_poly = poly_mult(res_poly, base, ct2, N)
        base = poly_mult(base, base, ct2, N)
        exp //= 2
    
    c1, c0 = res_poly
    rhs = (ct1 - c0) % N
    g = math.gcd(c1, N)
    if g == 1:
        inv_c1 = pow(c1, -1, N)
        msg = (rhs * inv_c1) % N
    else:
        p = g
        q = N // g
        phi = (p - 1) * (q - 1)
        d = pow(e, -1, phi)
        msg = pow(ct1, d, N)
    return msg

